css:
.sl-feature-journey {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3rem, 6vw, 5.5rem);
}
.sl-feature-journey h2,
.sl-feature-journey h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-feature-journey .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-feature-journey .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-feature-journey .sl-bg-card { background-color: var(--smartlearn-card-bg); }
.sl-feature-journey .sl-accent-soft {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, transparent);
}
.sl-feature-journey .sl-border { border-color: var(--smartlearn-card-border); }
.sl-feature-journey .sl-border-primary { border-color: var(--smartlearn-primary); }
.sl-feature-journey .sl-journey-subtitle { max-width: 600px; }
.sl-feature-journey .sl-media-fallback {
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text-muted);
}
.sl-feature-journey .sl-journey-connector {
    top: 70px;
    inset-inline: 12.5%;
    border-top: 2px dashed var(--smartlearn-card-border);
    pointer-events: none;
}
.sl-feature-journey .sl-step-media {
    width: 140px;
    height: 140px;
    border-width: 4px;
    border-style: solid;
    transition: transform 0.3s ease, border-color 0.3s ease;
}
@media (min-width: 992px) {
    .sl-feature-journey .sl-step-offset .sl-step-media {
        margin-top: 40px;
    }
}
.sl-feature-journey .sl-step-number {
    top: 0;
    inset-inline-end: 0;
    width: 34px;
    height: 34px;
    background-color: var(--smartlearn-card-bg);
    color: var(--smartlearn-text);
    border: 2px solid var(--smartlearn-card-border);
}
.sl-feature-journey .sl-step-number-primary {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
    border-color: var(--smartlearn-primary);
}
.sl-feature-journey .sl-step-img {
    transition: transform 0.5s ease;
}
.sl-feature-journey .sl-journey-step:hover .sl-step-media {
    transform: translateY(-8px);
    border-color: var(--smartlearn-primary);
}
.sl-feature-journey .sl-journey-step:hover .sl-step-img {
    transform: scale(1.08);
}
@keyframes sl-journey-fade-up {
    to { opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: no-preference) {
    .sl-feature-journey .sl-journey-step {
        opacity: 0;
        transform: translateY(30px);
        animation: sl-journey-fade-up 0.6s ease forwards;
    }
    .sl-feature-journey .sl-journey-step:nth-child(2) { animation-delay: 0.1s; }
    .sl-feature-journey .sl-journey-step:nth-child(3) { animation-delay: 0.2s; }
    .sl-feature-journey .sl-journey-step:nth-child(4) { animation-delay: 0.3s; }
    .sl-feature-journey .sl-journey-step:nth-child(5) { animation-delay: 0.4s; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-feature-journey .sl-step-media,
    .sl-feature-journey .sl-step-img {
        transition: none;
    }
    .sl-feature-journey .sl-journey-step:hover .sl-step-media,
    .sl-feature-journey .sl-journey-step:hover .sl-step-img {
        transform: none;
    }
}
